//! Fixed concurrent requests, including duplicated origins; application fixture only.
use std::{fs,num::NonZeroU32 as N,time::Instant};
use infinite_core::{CollisionMap,GridPosition as P};use infinite_runtime::{Config,ControlToken,Input,MovementRuntime,Phase};
fn n(v:u32)->N{N::new(v).unwrap()}
fn main(){let args:Vec<_>=std::env::args().collect();let data=fs::read_to_string(&args[1]).unwrap();let copies=args.get(2).map(|v|v.parse::<usize>().unwrap()).unwrap_or(2);assert!((1..=4).contains(&copies));let mut lines=data.lines();let size:Vec<u32>=lines.next().unwrap().split_whitespace().map(|v|v.parse().unwrap()).collect();let mut map=CollisionMap::new_staggered_connected(P{x:0,y:0},n(size[0]),n(size[1]),n(768),n(192)).unwrap();for(i,b)in lines.next().unwrap().bytes().enumerate(){if b==b'1'{map.set_blocked(i as u32%size[0],i as u32/size[0],true).unwrap();}}map.prepare_navigation();let all:Vec<Vec<i32>>=lines.map(|l|l.split_whitespace().map(|v|v.parse().unwrap()).collect()).collect();let q:Vec<_>=(0..16*copies).map(|i|&all[i%16*8]).collect();let mut r=MovementRuntime::new(map,Config{lease_ticks:20000,navigation_work:65536,..Config::default()}).unwrap();for(i,q)in q.iter().enumerate(){let token=ControlToken{id:i as u64+1,epoch:1};r.attach(token,P{x:q[0],y:q[1]},3200).unwrap();r.submit(token,1,Input::Goal(P{x:q[2],y:q[3]})).unwrap();}
let mut first=vec![0u64;q.len()];let mut done=vec![0u64;q.len()];let mut previous=q.iter().map(|q|P{x:q[0],y:q[1]}).collect::<Vec<_>>();let mut traces=vec![14695981039346656037u64;q.len()];let(mut steps,mut work,mut waiting,mut moved)=(0u64,0u64,0u64,0u64);let mut cpu=0u128;let mut samples=Vec::new();
while done.contains(&0){let start=Instant::now();let report=r.step().unwrap();let ns=start.elapsed().as_nanos();cpu+=ns;samples.push(ns);steps+=1;work+=u64::from(report.navigation_work);waiting+=report.waiting as u64;moved+=report.moved as u64;assert!(steps<20000&&report.navigation_work<=65536);for i in 0..q.len(){let s=r.view(i as u64+1).unwrap();assert!(!matches!(s.phase,Phase::Failed|Phase::Blocked));assert!(r.world().collision_map().unwrap().is_walkable(s.position));let dx=i64::from(s.position.x)-i64::from(previous[i].x);let dy=i64::from(s.position.y)-i64::from(previous[i].y);assert!(dx*dx+dy*dy<=162*162,"movement speed budget");if s.position!=previous[i]{if first[i]==0{first[i]=steps;}for v in [s.position.x,s.position.y]{traces[i]=(traces[i]^u64::from(v as u32)).wrapping_mul(1099511628211);}previous[i]=s.position;}if s.phase==Phase::Arrived&&done[i]==0{let dx=i64::from(s.position.x-q[i][2]);let dy=i64::from(s.position.y-q[i][3]);assert!(dx*dx+dy*dy<=80*80);done[i]=steps;}}}
samples.sort();println!("{{\"requests\":{},\"completed\":{},\"work\":{work},\"waiting_ticks\":{waiting},\"moved\":{moved},\"step_cpu_ms\":{},\"step_p99_ms\":{},\"first_ticks\":{first:?},\"arrival_ticks\":{done:?},\"traces\":{traces:?}}}",q.len(),done.len(),cpu as f64/1e6,samples[(samples.len()*99/100).min(samples.len()-1)]as f64/1e6);}
